using System.Collections.Concurrent;
using System.Diagnostics;
using System.Text.Json;
using CombatSolver.Engine.InCombat.Simulation;

namespace CombatSolver;

internal static class TaskExactQuotaWitness
{
    private sealed class Counts
    {
        internal readonly ConcurrentDictionary<string, long> WitnessValues = new();
        internal long EqualHp, EqualHpLateTurn, EqualHpGrowthUpperKnown, EqualHpGrowthUpperUnknown, EqualHpRealizedGrowth;
        internal readonly ConcurrentDictionary<string, long> EqualHpSources = new();
        internal long Visits, Eligible, Finite, Unknown, PaidWitness, PaidCut, StockWitness, StockCut, StockKnown, Ticks;
    }
    private static readonly ConcurrentDictionary<string, Counts> Items = new();
    internal static ClosedInitialPotionInventory? CaptureStock(CombatRootSnapshot root)
        => root.UsesPruningComponentHealingCertificate
            ? ClosedInitialPotionInventory.Capture(root.ForkSimulator(), root.PlayerIdentity,
                root.HasRenewablePotionShapedRock, useReviewedSources: true) : null;
    internal static void Record(string key, bool eligible, bool finite, bool paidWitness, bool paidCut,
        bool stockWitness, bool stockCut, bool stockKnown, long ticks, int? witnessHp, int? witnessCost)
    {
        var c = Items.GetOrAdd(key, _ => new());
        Interlocked.Increment(ref c.Visits);
        if (eligible) Interlocked.Increment(ref c.Eligible);
        if (finite) Interlocked.Increment(ref c.Finite);
        if (eligible && !finite) Interlocked.Increment(ref c.Unknown);
        if (paidWitness) Interlocked.Increment(ref c.PaidWitness);
        if (paidCut) Interlocked.Increment(ref c.PaidCut);
        if (stockWitness) Interlocked.Increment(ref c.StockWitness);
        if (stockCut) Interlocked.Increment(ref c.StockCut);
        if (stockKnown) Interlocked.Increment(ref c.StockKnown);
        if (stockWitness) c.WitnessValues.AddOrUpdate("hp=" + witnessHp + "/cost=" + witnessCost + "/cut=" + stockCut, 1, (_, old) => old + 1);
        Interlocked.Add(ref c.Ticks, ticks);
    }
    internal static void RecordEquality(string key, SearchNode node, PrimarySearchIncumbent incumbent,
        CombatPredictionSimulator simulator, MegaCrit.Sts2.Core.Entities.Players.Player player)
    {
        var c = Items.GetOrAdd(key, _ => new());
        Interlocked.Increment(ref c.EqualHp);
        if (node.Turn > incumbent.CombatEndedTurn) Interlocked.Increment(ref c.EqualHpLateTurn);
        if (node.Snapshot.GrowthRewards.Total > 0) Interlocked.Increment(ref c.EqualHpRealizedGrowth);
        var upper = ResourceIncumbentPolicy.CaptureExhaustingGrowthUpperBound(simulator, player);
        if (upper.HasValue) Interlocked.Increment(ref c.EqualHpGrowthUpperKnown);
        else Interlocked.Increment(ref c.EqualHpGrowthUpperUnknown);
        var cards = simulator.State.GetPlayerCombatState(player);
        foreach (var card in cards.AllCards)
        {
            string source = "card/" + card.Preview.GetType().FullName
                + "/growth=" + GrowthValues.HasTarget(card.Preview)
                + "/exhausted=" + cards.ExhaustPile.Cards.Contains(card);
            c.EqualHpSources.AddOrUpdate(source, 1, (_, old) => old + 1);
        }
        var combat = (SimulatedCombatState)simulator.State.CombatState;
        foreach (var power in combat.EffectivePowers())
            c.EqualHpSources.AddOrUpdate("power/" + power.GetType().FullName, 1, (_, old) => old + 1);
    }
    internal static string Snapshot() => JsonSerializer.Serialize(Items.OrderBy(p => p.Key).Select(p => new {
        key = p.Key, visits = p.Value.Visits, eligible = p.Value.Eligible,
        finite = p.Value.Finite, unknown = p.Value.Unknown,
        paidWitness = p.Value.PaidWitness, paidCut = p.Value.PaidCut,
        stockWitness = p.Value.StockWitness, stockCut = p.Value.StockCut,
        stockKnown = p.Value.StockKnown, equalHp = p.Value.EqualHp, equalHpLateTurn = p.Value.EqualHpLateTurn, equalHpGrowthUpperKnown = p.Value.EqualHpGrowthUpperKnown, equalHpGrowthUpperUnknown = p.Value.EqualHpGrowthUpperUnknown, equalHpRealizedGrowth = p.Value.EqualHpRealizedGrowth, equalHpSources = p.Value.EqualHpSources, witnessValues = p.Value.WitnessValues,
        cumulativeQueryWallMs = p.Value.Ticks * 1000.0 / Stopwatch.Frequency }).ToArray());
}

internal sealed partial class CombatBeamSolver
{
    private readonly ClosedInitialPotionInventory? _taskReviewedPotionStock = TaskExactQuotaWitness.CaptureStock(root);
    private void ObserveExactQuotaSharedWitness(SearchNode node, bool closed)
    {
        if (closed || _minimumPotionUses <= 0 || _maximumPotionUses != _minimumPotionUses) return;
        long started = Stopwatch.GetTimestamp();
        bool eligible = root.UsesPruningComponentHealingCertificate
            && _useSharedPrimaryIncumbents && !_potionStrategy.HasForcedDirectives
            && policy.EffectiveGrowthBudgets == default && policy.RelicTargets.Count == 0
            && _theftPolicy != SolverTheftPolicy.PreserveResources
            && !node.IsTerminal && node.Snapshot.HasSimulator && !node.Snapshot.HasRisk
            && node.Snapshot.BoundaryReason == SearchBoundaryReason.None
            && node.Snapshot.OutstandingStolenResource == 0 && node.Snapshot.StrategicHpCredit == 0;
        int? witnessHp = null, witnessCost = null;
        bool finite = false, paidWitness = false, paidCut = false, stockWitness = false, stockCut = false, stockKnown = false;
        if (eligible)
        {
            var sim = (CombatPredictionSimulator)node.Snapshot.Simulator;
            int healing = StrategicHpRecoveryBound.ComponentHealingUpperBound(sim, _player,
                root.PostCombatRelicHeal.UnconditionalHeal + root.PostCombatRelicHeal.WoundedHeal,
                includePotionHealing: true, maximumExplicitPotionUses: _maximumPotionUses,
                potionStrategy: _potionStrategy, effectivePotionPolicy: _potionPolicy, useReviewedSources: true);
            finite = healing != int.MaxValue;
            if (finite)
            {
                int hp = StrategicHpLowerBound(node.Snapshot, _strategicBossHpRelief, healing);
                paidWitness = _primaryIncumbents.TryGetStrictHpWitness(0, _minimumPotionUses,
                    node.Snapshot.ExplicitPotionStrategicCost, out var incumbent);
                paidCut = paidWitness && hp > incumbent.StrategicHpDeficit;
                int? floor = _taskReviewedPotionStock?.MinimumExplicitCost(sim, _player, _minimumPotionUses, healing);
                stockKnown = floor.HasValue;
                if (floor.HasValue)
                {
                    stockWitness = _primaryIncumbents.TryGetStrictHpWitness(0, _minimumPotionUses,
                        floor.Value, out incumbent);
                    stockCut = stockWitness && hp > incumbent.StrategicHpDeficit;
                    if (stockWitness && hp == incumbent.StrategicHpDeficit)
                        TaskExactQuotaWitness.RecordEquality((_directSearchPurpose?.ToString() ?? _attributionPurpose?.ToString() ?? "unspecified")
                            + "/quota=" + _minimumPotionUses + "/uses=" + ExplicitPotionUseCount(node)
                            + "/reviewedStock=" + (_taskReviewedPotionStock is not null), node, incumbent, sim, _player);
                    if (stockWitness) { witnessHp = incumbent.StrategicHpDeficit; witnessCost = incumbent.ExplicitPotionStrategicCost; }
                }
            }
        }
        string key = (_directSearchPurpose?.ToString() ?? _attributionPurpose?.ToString() ?? "unspecified")
            + "/quota=" + _minimumPotionUses + "/uses=" + ExplicitPotionUseCount(node)
            + "/reviewedStock=" + (_taskReviewedPotionStock is not null);
        TaskExactQuotaWitness.Record(key, eligible, finite, paidWitness, paidCut, stockWitness, stockCut,
            stockKnown, Stopwatch.GetTimestamp() - started, witnessHp, witnessCost);
    }
}

